package com.example.rewards.service;
import com.example.rewards.dto.CustomerRewardsResponse; import com.example.rewards.model.MonthlyReward; import com.example.rewards.model.Transaction; import com.example.rewards.repository.TransactionRepository; import org.springframework.stereotype.Service; import java.time.YearMonth; import java.util.*;
@Service public class RewardsService { private final TransactionRepository transactionRepository; private final RewardPointsCalculator rewardPointsCalculator;
 public RewardsService(TransactionRepository r,RewardPointsCalculator c){transactionRepository=r;rewardPointsCalculator=c;}
 public List<CustomerRewardsResponse> getRewardsForAllCustomers(){return transactionRepository.findAll().stream().map(Transaction::customerId).distinct().map(this::getRewardsForCustomer).toList();}
 public CustomerRewardsResponse getRewardsForCustomer(String customerId){List<Transaction> customerTransactions=transactionRepository.findAll().stream().filter(t->t.customerId().equalsIgnoreCase(customerId)).sorted(Comparator.comparing(Transaction::transactionDate)).toList(); if(customerTransactions.isEmpty())throw new IllegalArgumentException("Customer not found: "+customerId); Map<YearMonth,Integer> pointsByMonth=new TreeMap<>(); for(Transaction transaction:customerTransactions){pointsByMonth.merge(YearMonth.from(transaction.transactionDate()),rewardPointsCalculator.calculateRewardPoints(transaction.transactionAmount()),Integer::sum);} List<MonthlyReward> monthlyRewards=pointsByMonth.entrySet().stream().map(e->new MonthlyReward(e.getKey().toString(),e.getValue())).toList(); return new CustomerRewardsResponse(customerTransactions.get(0).customerId(),customerTransactions.get(0).customerName(),monthlyRewards,monthlyRewards.stream().mapToInt(MonthlyReward::rewardPoints).sum());}
 public List<Transaction> getTransactions(String customerId,YearMonth startMonth,YearMonth endMonth){if(startMonth!=null&&endMonth!=null&&startMonth.isAfter(endMonth))throw new IllegalArgumentException("startMonth must be before or equal to endMonth"); return transactionRepository.findAll().stream().filter(t->customerId==null||customerId.isBlank()||t.customerId().equalsIgnoreCase(customerId)).filter(t->{YearMonth m=YearMonth.from(t.transactionDate());return(startMonth==null||!m.isBefore(startMonth))&&(endMonth==null||!m.isAfter(endMonth));}).sorted(Comparator.comparing(Transaction::transactionDate)).toList();}
}
